package com.movieticket.booking;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;public interface BookingRepository extends JpaRepository<Booking,Long>{List<Booking> findByEmailOrderByBookedAtDesc(String email);Optional<Booking> findByIdAndEmail(Long id,String email);boolean existsByShowIdAndSeatNumberAndStatus(Long showId,String seatNumber,String status);}